func canonicalKind(kind string) string {
	switch kind {
	case "docx":
		return "word"
	case "xlsx":
		return "spreadsheet"
	case "pptx":
		return "presentation"
	default:
		return kind
	}
}

func Build(kind string) ([]byte, string, error) {
	t, ok := templates[canonicalKind(kind)]
	if !ok {
		return nil, "", ErrInvalidKind
	}
	var out bytes.Buffer
	zw := zip.NewWriter(&out)
	for name, content := range t.entries {
		w, err := zw.Create(name)
		if err != nil {
			return nil, "", err
		}
		if _, err := w.Write([]byte(content)); err != nil {
			return nil, "", err
		}
	}
	if err := zw.Close(); err != nil {
		return nil, "", err
	}
	return out.Bytes(), t.name, nil
}

func Extension(kind string) (string, error) {
	t, ok := templates[canonicalKind(kind)]
	if !ok {
		return "", ErrInvalidKind
	}
	return t.ext, nil
}
